 @Test void manualOffPausesCycleAndPreventsSecondAutomaticOff()throws Exception{var r=afterOn();step(r,"OFF");timer(r.sessionId());cycle.poll();assertEquals("PAUSED",state(r.sessionId()).state());assertEquals(1,count("pump_command","OFF"));}
 @Test void externalEmergencyOffTakesOverWithoutAutomaticClose()throws Exception{var r=afterOn();fencing.createHttp(request("OFF",null,null),()->{});cycle.poll();assertEquals("INTERRUPTED",state(r.sessionId()).state());assertEquals(1,count("pump_command","OFF"));assertEquals(0,count("circuit_demo_command","CLOSE"));}
