 @Test void lateOpenCommitIsRejectedWhenPauseWins()throws Exception{var controlled=spy(org.springframework.test.util.AopTestUtils.<CircuitValveControl>getUltimateTargetObject(valves));var localSession=new IrrigationSession(jdbc,mapper,circuits,controlled,pump,fencing,proof,manager,true,false);localSession.interruptOnStartup();var local=new IrrigationCycle(jdbc,mapper,localSession,manager,true);var r=begin();var c=armCycle(r);doAnswer(call->{cycle.pause("PR1",r.sessionId(),c.armId());return call.callRealMethod();}).when(controlled).create(anyString(),any(),any());local.poll();assertEquals("PAUSED",state(r.sessionId()).state());assertEquals(0,count("circuit_demo_command","OPEN"));}

 @Test void waterSupervisorAndCycleTimerShareOneStopClaim()throws Exception{var r=afterOn();onConfirmed(r);jdbc.update("INSERT INTO circuit_water_gate(circuit_id,circuit_revision,enabled,revision,stop_on_unavailable) VALUES('PR1',1,true,1,true)");timer(r.sessionId());try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){for(var f:pool.invokeAll(List.<java.util.concurrent.Callable<Void>>of(()->{cycle.poll();return null;},()->{service.stopForWater();return null;})))f.get();}cycle.poll();assertEquals(1,count("pump_command","OFF"));assertEquals(0,count("circuit_demo_command","CLOSE"));}
 @Test void lateOnCommitAfterStopCutoffIsRejectedThenOffIsAttemptedOnce()throws Exception{var controlled=spy(org.springframework.test.util.AopTestUtils.<PumpCommandFencing>getUltimateTargetObject(fencing));var localSession=new IrrigationSession(jdbc,mapper,circuits,valves,pump,controlled,proof,manager,true,false);localSession.interruptOnStartup();var local=new IrrigationCycle(jdbc,mapper,localSession,manager,true);var r=begin();armCycle(r);local.poll();opened(current(r.sessionId()));doAnswer(call->{timer(r.sessionId());return call.callRealMethod();}).when(controlled).createHttp(any(),any());local.poll();local.poll();local.poll();assertEquals(0,count("pump_command","ON"));assertEquals(1,count("pump_command","OFF"));}
